def sha256_text(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def webgpt_receipt_text(phase_subject_sha256: str, extra: str = "", skill_context_sha256: str = "skill-context") -> str:
    prefix = (
        '{"adjudicator_kind":"webgpt","clean_contains_sentinel":false,'
        '"activated":false,"controlled_tab_id":"123","controlled_tab_id_mismatch":false,"focus_changed":false,'
        '"no_activate":true,"raw_contains_sentinel":true,'
        '"request_sha256":"'
        + sha256_text("request")
        + '","response_sha256":"'
        + sha256_text("review")
        + '","review_bundle_sha256":"'
        + sha256_text("bundle")
        + '","phase_subject_sha256":"'
        + phase_subject_sha256
        + '","skill_context_sha256":"'
        + skill_context_sha256
        + '","reviewer_id":"webgpt","sentinel":"<<<WEBGPT_DONE:fixture>>>","status":"completed"'
    )
    return prefix + extra + "}"


def review_result(
    reviewer_id: str = "webgpt",
    verdict: str = "pass",
    artifact: str = "reviews/review.md",
    phase_subject_sha256: str = "phase-subject",
    skill_context_sha256: str = "skill-context",
) -> dict[str, object]:
    receipt_text = webgpt_receipt_text(phase_subject_sha256, skill_context_sha256=skill_context_sha256)
    return {
        "reviewer_id": reviewer_id,
        "adjudicator_kind": "webgpt" if reviewer_id == "webgpt" else "scillm",
        "verdict": verdict,
        "artifact": artifact,
        "artifact_sha256": sha256_text("review"),
        "review_request_artifact": "reviews/request.md",
        "review_request_sha256": sha256_text("request"),
        "review_bundle_artifact": "reviews/bundle.zip",
        "review_bundle_sha256": sha256_text("bundle"),
        "phase_subject_sha256": phase_subject_sha256,
        "skill_context_sha256": skill_context_sha256,
        "invocation": {
            "tool": "surf webgpt.submit",
            "command_or_run_id": "run-1",
            "receipt_artifact": "reviews/receipt.json",
            "receipt_sha256": sha256_text(receipt_text),
            "model": None,
        },
        "recorded_at": "20260514T000000Z",
    }


